namespace Fanex.Tarus.BetList.Helper
{
    using System;
    using System.Diagnostics.CodeAnalysis;
    using Fanex.Tarus.BetList.DataAccess;

    [SuppressMessage("Microsoft.StyleCop.CSharp.DocumentationRules", "SA1600:ElementsMustBeDocumented")]
    public class ReportServices
    {
        public const string BET_TRANS14_SP_SUFFIX = "_14";
        public const string WARE_HOUSE_SP_SUFFIX = "_WH";

        public static string GetStoreMappingSubfix(DateTime reportDate)
        {
            if (reportDate > ReportDataAccess.BalanceUp.MoveBetsDay)
            {
                return string.Empty;
            }
            else if (reportDate >= ReportDataAccess.BalanceUp.BalanceUpDay)
            {
                return BET_TRANS14_SP_SUFFIX;
            }
            else
            {
                return WARE_HOUSE_SP_SUFFIX;
            }
        }
    }
}
